package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked for update until the transaction ends. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findLockedById(String id);

    /** The sheets naming this one as their parent. */
    List<Sheet> findByParentIdOrderByIdAsc(String parentId);
}
    public void setParentId(String parentId) {
        this.parentId = parentId;
    }

    public boolean isArchived() {
        return archived;
    }

    public void archive() {
        this.archived = true;
    }

    /** The last claim number given on the sheet; 0 when there has been none. */
    public long getLastClaimNumber() {
        return lastClaimNumber;
    }

    /** Take a claim number following the last given anywhere in the sheet's tree. */
    public long takeClaimNumberAfter(long lastInTree) {
        lastClaimNumber = Math.max(lastClaimNumber, lastInTree) + 1;
        return lastClaimNumber;
    }

    /** The last settle batch number given on the sheet; null when there has been none. */
    public Long getLastBatchNumber() {
        return lastBatchNumber == 0 ? null : lastBatchNumber;
    }

    /** Take the sheet's next settle batch number. */
    public long nextBatchNumber() {
        return ++lastBatchNumber;
    }
}

